begin;
set local lock_timeout='3s';set local statement_timeout='60s';
create temporary table tecnica_test(actor uuid,company_id uuid,order_id uuid,pos_id uuid,contenuto jsonb);
insert into tecnica_test select sp.user_id,sp.company_id,o.id,gen_random_uuid(),null from public.staff_permissions sp join public.orders o on o.company_id=sp.company_id where sp.can_view_sicurezza_cantiere and not sp.sola_lettura and o.deleted_at is null and exists(select 1 from public.orders x where x.company_id=o.company_id and x.id<>o.id and x.deleted_at is null) limit 1;
grant select on tecnica_test to authenticated,service_role;
do $$begin if not exists(select 1 from tecnica_test) then raise exception 'Azienda di prova assente';end if;end$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true) from tecnica_test;
update tecnica_test set contenuto='{"versione_modello": 1, "versione_controlli": 2, "versione_tecnica": 1, "formazione": [], "lavorazioni": [{"id": "l1", "titolo": "TEST SCHEDA TECNICA", "tecnica": {"area": "TEST area", "interferenze": "TEST interferenze", "condizioni_avvio": "TEST condizioni_avvio", "sospensione": "TEST sospensione", "emergenze": "TEST emergenze", "prima": "TEST prima", "durante": "TEST durante", "dopo": "TEST dopo", "riesaminata": true, "attrezzature_previste": "si", "motivo_senza_attrezzature": "", "rischi": [{"id": "r1", "pericolo": "TEST pericolo", "esposti": "TEST esposti", "situazione": "TEST situazione", "valutazione_iniziale": "TEST valutazione_iniziale", "misure_collettive": "TEST misure_collettive", "misure_organizzative": "TEST misure_organizzative", "dpi": "TEST dpi", "valutazione_residua": "TEST valutazione_residua", "riferimento": "TEST riferimento"}], "attrezzature": [{"id": "a1", "nome": "TEST nome", "identificativo": "TEST identificativo", "impiego": "TEST impiego", "controlli_preuso": "TEST controlli_preuso", "manuale_riferimento": "TEST manuale_riferimento", "formazione_addestramento": "TEST formazione_addestramento"}]}}]}'::jsonb;
create temporary table mezzo_test(a1 uuid default gen_random_uuid(),a2 uuid default gen_random_uuid(),q uuid default gen_random_uuid(),parent uuid default gen_random_uuid(),child uuid default gen_random_uuid(),fuori uuid default gen_random_uuid(),altro uuid,fonte jsonb,prova jsonb);
insert into mezzo_test(altro)select id from public.orders where company_id=(select company_id from tecnica_test) and id<>(select order_id from tecnica_test) and deleted_at is null limit 1;
grant select on mezzo_test to authenticated,service_role;
insert into public.mezzi(id,company_id,nome,tipo,assegnato_order_id,matricola,note,valore_acquisto)
select v.id,f.company_id,'TEST MEZZI POS OMONIMO',v.tipo,v.ordine,v.id::text,'TEST NOTA PRIVATA',999 from tecnica_test f cross join mezzo_test t cross join lateral(values(t.a1,'attrezzatura',f.order_id),(t.a2,'attrezzatura',f.order_id),(t.parent,'furgone',f.order_id),(t.fuori,'attrezzatura',t.altro))v(id,tipo,ordine);
update public.mezzi_assegnazioni set dal='2026-11-01 00:00 Europe/Rome',al='2026-12-01 00:00 Europe/Rome' where mezzo_id=(select a1 from mezzo_test);
-- Legacy current placement has no historical assignment. Never edit real rows.
delete from public.mezzi_assegnazioni where mezzo_id=(select a2 from mezzo_test);
insert into public.mezzi(id,company_id,nome,tipo,su_mezzo_id) select t.child,f.company_id,'TEST MEZZI POS CARICATO','attrezzatura',t.parent from tecnica_test f cross join mezzo_test t;
insert into public.mezzi(id,company_id,nome,tipo,gestione,quantita_totale,unita_misura) select t.q,f.company_id,'TEST MEZZI POS QUANTITA','attrezzatura','quantita',10,'mq' from tecnica_test f cross join mezzo_test t;
insert into public.mezzi_allocazioni(company_id,mezzo_id,order_id,quantita,dal,al) select f.company_id,t.q,f.order_id,2.5,'2026-11-01','2026-11-30' from tecnica_test f cross join mezzo_test t;
update mezzo_test set fonte=(select public.pos_mezzo_fotografia(f.company_id,f.order_id,t.a1,'assegnazione',a.id) from tecnica_test f cross join mezzo_test t join public.mezzi_assegnazioni a on a.mezzo_id=t.a1);
update tecnica_test set contenuto=contenuto||jsonb_build_object('versione_mezzi',1,'opera',jsonb_build_object('data_inizio','2026-11-01','data_fine','2026-11-30'));
update tecnica_test set contenuto=jsonb_set(contenuto,'{lavorazioni,0,tecnica,attrezzature,0,anagrafica}',jsonb_build_object('modalita','inventario','motivazione','','fonte',(select fonte from mezzo_test),'utilizzo_dal','2026-11-02','utilizzo_al','2026-11-20','quantita_usata',1,'confermata',true));

create temporary table doc_mezzo_test(d uuid default gen_random_uuid(),economico uuid default gen_random_uuid(),altro uuid default gen_random_uuid(),senza_file uuid default gen_random_uuid(),manutenzione uuid default gen_random_uuid(),segnalazione uuid default gen_random_uuid(),prova jsonb,contenuto jsonb);
insert into doc_mezzo_test default values;grant select on doc_mezzo_test to authenticated,service_role;
insert into storage.objects(bucket_id,name,version,metadata)select 'mezzi-documenti',f.company_id::text||'/'||t.a1::text||'/test-manuale.pdf','TEST-V1','{"size":10,"eTag":"TEST-ETAG"}'::jsonb from tecnica_test f cross join mezzo_test t;
insert into public.mezzi_documenti(id,company_id,mezzo_id,categoria,titolo,data_inizio,data_scadenza,file_path,file_name,importo,note)
select v.id,f.company_id,v.mezzo,v.categoria,'TEST DOC MEZZO','2026-11-01','2026-11-30',v.path,'test-manuale.pdf',12345,'TEST NOTA PRIVATA' from tecnica_test f cross join mezzo_test t cross join doc_mezzo_test d cross join lateral(values(d.d,t.a1,'manuale_ce',f.company_id::text||'/'||t.a1::text||'/test-manuale.pdf'),(d.economico,t.a1,'contratto',null::text),(d.altro,t.a2,'libretto',null::text),(d.senza_file,t.a1,'libretto',f.company_id::text||'/'||t.a2::text||'/estraneo.pdf'))v(id,mezzo,categoria,path);
insert into public.mezzi_manutenzioni(id,company_id,mezzo_id,tipo,data,costo,descrizione,prossima_data,prossimo_contatore)select d.manutenzione,f.company_id,t.a1,'verifica','2026-10-01',9999,'TEST DESCRIZIONE RISERVATA','2026-12-01',100 from tecnica_test f cross join mezzo_test t cross join doc_mezzo_test d;
insert into public.mezzi_segnalazioni(id,company_id,mezzo_id,tipo,descrizione,stato)select d.segnalazione,f.company_id,t.a1,'guasto','TEST DESCRIZIONE RISERVATA','aperta' from tecnica_test f cross join mezzo_test t cross join doc_mezzo_test d;
update doc_mezzo_test d set contenuto=jsonb_set(f.contenuto||jsonb_build_object('versione_documenti_mezzi',1),'{lavorazioni,0,tecnica,attrezzature,0,documentazione}',jsonb_build_object('modalita','documenti','motivazione','','documenti',jsonb_build_array((select public.pos_documento_mezzo_foto(x)||jsonb_build_object('confermata',true,'revisione_dichiarata','TEST-1')from public.mezzi_documenti x where x.id=d.d)),'controlli',public.pos_controlli_mezzo_foto(f.company_id,t.a1),'riesame_controlli','TEST riesame da tecnico, nessun esito reale','confermata',true))from tecnica_test f cross join mezzo_test t;
set local role authenticated;
do $$declare f record;t record;d record;q jsonb;begin select * into f from tecnica_test;select * into t from mezzo_test;select * into d from doc_mezzo_test;
 q:=public.pos_documenti_mezzo_quadro(f.company_id,f.order_id,t.a1);
 if jsonb_array_length(q->'documenti')<>2 or exists(select 1 from jsonb_array_elements(q->'documenti')x where x->>'id' not in(d.d::text,d.senza_file::text)) then raise exception 'ASSERT: ambito o categorie';end if;
 if q::text like '%file_path%' or q::text like '%importo%' or q::text like '%costo%' or q::text like '%TEST DESCRIZIONE RISERVATA%' or q::text like '%TEST NOTA PRIVATA%' then raise exception 'ASSERT: proiezione riservata';end if;
 if exists(select 1 from jsonb_array_elements(q->'documenti')x where x->>'id'=d.senza_file::text and x->'disponibile'='true'::jsonb) then raise exception 'ASSERT: path altra macchina';end if;
 begin perform public.pos_documenti_mezzo_quadro(gen_random_uuid(),f.order_id,t.a1);raise exception 'ASSERT: altra azienda';exception when insufficient_privilege then null;end;
 if has_function_privilege('authenticated','public.pos_documenti_mezzi_verifica(uuid,uuid,jsonb)','execute') or has_function_privilege('anon','public.pos_documenti_mezzo_quadro(uuid,uuid,uuid)','execute') then raise exception 'ASSERT: privilegi';end if;
end$$;
reset role;
set local role service_role;
do $$declare f record;d record;v jsonb;begin select * into f from tecnica_test;select * into d from doc_mezzo_test;
 perform public.pos_documento_mezzo_per_autore(f.company_id,f.order_id,(select a1 from mezzo_test),d.d,d.contenuto->'lavorazioni'->0->'tecnica'->'attrezzature'->0->'documentazione'->'documenti'->0->>'impronta',f.actor);
 begin perform public.pos_documento_mezzo_per_autore(f.company_id,f.order_id,(select a1 from mezzo_test),d.altro,'a',f.actor);raise exception 'ASSERT: documento altra macchina';exception when insufficient_privilege then null;end;
 begin perform public.pos_documento_mezzo_per_autore(f.company_id,f.order_id,(select a1 from mezzo_test),d.d,'a',gen_random_uuid());raise exception 'ASSERT: autore non autorizzato';exception when insufficient_privilege then null;end;
 v:=public.pos_documenti_mezzi_verifica(f.company_id,f.order_id,d.contenuto);
 if jsonb_array_length(v->'allegati')<>1 or v->'allegati'->0->>'bucket'<>'mezzi-documenti' then raise exception 'ASSERT: origine originale';end if;
 begin perform public.pos_documenti_mezzi_verifica(f.company_id,f.order_id,jsonb_set(d.contenuto,'{lavorazioni,0,tecnica,attrezzature,0,documentazione,documenti,0,confermata}','false'));raise exception 'ASSERT: conferma documento';exception when raise_exception then if sqlerrm like 'ASSERT:%' then raise;end if;end;
 begin perform public.pos_documenti_mezzi_verifica(f.company_id,f.order_id,jsonb_set(d.contenuto,'{lavorazioni,0,tecnica,attrezzature,0,documentazione,documenti,0,revisione_dichiarata}','""'));raise exception 'ASSERT: revisione letta';exception when raise_exception then if sqlerrm like 'ASSERT:%' then raise;end if;end;
end$$;
reset role;
do $$declare f record;d record;begin select * into f from tecnica_test;select * into d from doc_mezzo_test;
 begin
  update public.mezzi_documenti set data_scadenza='2026-11-10' where id=d.d;
  d.contenuto:=jsonb_set(d.contenuto,'{lavorazioni,0,tecnica,attrezzature,0,documentazione,controlli}',public.pos_controlli_mezzo_foto(f.company_id,(select a1 from mezzo_test)));
  d.contenuto:=jsonb_set(d.contenuto,'{lavorazioni,0,tecnica,attrezzature,0,documentazione,documenti,0}',(select public.pos_documento_mezzo_foto(x)||jsonb_build_object('confermata',true,'revisione_dichiarata','TEST-1')from public.mezzi_documenti x where x.id=d.d));
  perform public.pos_documenti_mezzi_verifica(f.company_id,f.order_id,d.contenuto);raise exception 'ASSERT: scadenza durante impiego';
 exception when raise_exception then if sqlerrm<>'Documento attrezzatura non valido per tutto l’uso dichiarato' then raise;end if;end;
 select * into d from doc_mezzo_test;
 begin update public.mezzi_segnalazioni set stato='in_lavorazione' where id=d.segnalazione;perform public.pos_documenti_mezzi_verifica(f.company_id,f.order_id,d.contenuto);raise exception 'ASSERT: nuovi controlli ignorati';exception when serialization_failure then null;end;
 begin update storage.objects set version='TEST-V2' where bucket_id='mezzi-documenti' and name like f.company_id::text||'/%/test-manuale.pdf';perform public.pos_documenti_mezzi_verifica(f.company_id,f.order_id,d.contenuto);raise exception 'ASSERT: sovrascrittura stesso path';exception when serialization_failure then null;end;
end$$;
insert into public.pos_documents(id,company_id,order_id,tipo_lavori,indirizzo_cantiere,status,revisione,contenuto,iter,updated_at) select f.pos_id,f.company_id,f.order_id,'TEST DOCUMENTI MEZZI POS ROLLBACK','Indirizzo sintetico','bozza',0,d.contenuto,'{}',clock_timestamp() from tecnica_test f cross join doc_mezzo_test d;
alter table doc_mezzo_test add column emissione jsonb,add column manifest jsonb;
update doc_mezzo_test d set emissione=public.pos_prenota_emissione(f.pos_id,f.actor,p.updated_at,null),prova=public.pos_documenti_mezzi_fonti_emissione(f.pos_id,f.actor) from tecnica_test f join public.pos_documents p on p.id=f.pos_id;
update doc_mezzo_test d set manifest=jsonb_build_object('emissioneId',d.emissione->>'id','companyId',f.company_id,'posId',f.pos_id,'revisione',0,'origine','approvazione_corrente','mezzi_pos',public.pos_mezzi_verifica(f.company_id,f.order_id,d.contenuto),'file',(select jsonb_agg(jsonb_build_object('nome',n,'path',f.company_id::text||'/'||(d.emissione->>'id')||'/'||(d.emissione->>'token')||'/'||n,'sha256',repeat('a',64),'dimensione',1))from unnest(array['POS.pdf','modello.html','fonti.json'])n))from tecnica_test f;
insert into storage.objects(bucket_id,name)select 'pos-emissioni',f.company_id::text||'/'||(d.emissione->>'id')||'/'||(d.emissione->>'token')||'/'||n from doc_mezzo_test d cross join tecnica_test f cross join unnest(array['POS.pdf','modello.html','fonti.json','manifest.json','fascicolo.zip','ATTREZZATURA.pdf'])n;
set local role service_role;
do $$declare f record;d record;v jsonb;begin select * into f from tecnica_test;select * into d from doc_mezzo_test;
 begin perform public.pos_completa_emissione((d.emissione->>'id')::uuid,(d.emissione->>'token')::uuid,f.actor,'TEST',d.manifest,repeat('b',64),repeat('c',64));raise exception 'ASSERT: manifest V assente';exception when raise_exception then if sqlerrm<>'Il pacchetto non conserva documenti e controlli attrezzatura riesaminati' then raise;end if;end;
 v:=d.manifest||jsonb_build_object('documenti_mezzi',jsonb_build_object('versione',1,'collegamenti',d.prova->'collegamenti'));
 begin perform public.pos_completa_emissione((d.emissione->>'id')::uuid,(d.emissione->>'token')::uuid,f.actor,'TEST',v,repeat('b',64),repeat('c',64));raise exception 'ASSERT: originale macchina assente';exception when raise_exception then if sqlerrm<>'Originale della specifica attrezzatura non conservato nel pacchetto' then raise;end if;end;
end$$;
reset role;
update doc_mezzo_test d set manifest=d.manifest||jsonb_build_object('documenti_mezzi',jsonb_build_object('versione',1,'collegamenti',d.prova->'collegamenti'),'file',(d.manifest->'file')||jsonb_build_array(jsonb_build_object('nome','ATTREZZATURA.pdf','path',f.company_id::text||'/'||(d.emissione->>'id')||'/'||(d.emissione->>'token')||'/ATTREZZATURA.pdf','sha256',repeat('d',64),'dimensione',1,'ruolo','allegato','tipo','documento_attrezzatura','evidenza_id',d.d,'mezzo_id',t.a1,'impronta_metadati',d.prova->'allegati'->0->>'impronta','fonte',jsonb_build_object('bucket','mezzi-documenti','path',d.prova->'allegati'->0->>'path'))))from tecnica_test f cross join mezzo_test t;
do $$declare f record;d record;begin select * into f from tecnica_test;select * into d from doc_mezzo_test;
 begin update storage.objects set version='TEST-V3' where bucket_id='mezzi-documenti' and name like f.company_id::text||'/%/test-manuale.pdf';perform public.pos_completa_emissione((d.emissione->>'id')::uuid,(d.emissione->>'token')::uuid,f.actor,'TEST',d.manifest,repeat('b',64),repeat('c',64));raise exception 'ASSERT: originale sostituito durante rendering';exception when serialization_failure then null;end;
end$$;
set local role service_role;
select public.pos_completa_emissione((d.emissione->>'id')::uuid,(d.emissione->>'token')::uuid,f.actor,'TEST DOCUMENTI MEZZI',d.manifest,repeat('b',64),repeat('c',64)) from doc_mezzo_test d cross join tecnica_test f;
reset role;
do $$begin if not exists(select 1 from public.pos_documents p join tecnica_test f on f.pos_id=p.id where p.status='approvato') then raise exception 'ASSERT: finalizzazione non approva';end if;end$$;
select 'PASS: fonti native macchina/documento, privacy, periodo/originali/controlli con rollback; nessun upload fisico' as risultato;
rollback;
